import type { SearchResponse, SearchResultSummary } from "@endeavour/vue-library/models";

export type MemberChange = "added" | "removed" | "unchanged";

export interface ComparedMember extends SearchResultSummary {
  change: MemberChange;
}

export interface MemberComparison {
  /** Saved members, each flagged as "removed" (not in the new definition) or "unchanged" */
  current: ComparedMember[];
  /** Members generated by the new definition, each flagged as "added" (not currently saved) or "unchanged" */
  updated: ComparedMember[];
  added: number;
  removed: number;
  unchanged: number;
}

function byName(a: SearchResultSummary, b: SearchResultSummary): number {
  return (a.name ?? a.iri).localeCompare(b.name ?? b.iri, undefined, { sensitivity: "base" });
}

function uniqueByIri(members: SearchResultSummary[] | undefined): Map<string, SearchResultSummary> {
  const map = new Map<string, SearchResultSummary>();
  for (const member of members ?? []) if (!map.has(member.iri)) map.set(member.iri, member);
  return map;
}

/**
 * Compares the currently saved members of a set with the members generated by a new definition.
 * Members are matched on iri.
 */
export function compareMembers(currentMembers?: SearchResponse, newMembers?: SearchResponse): MemberComparison {
  const currentByIri = uniqueByIri(currentMembers?.entities);
  const updatedByIri = uniqueByIri(newMembers?.entities);

  const current: ComparedMember[] = [...currentByIri.values()]
    .map(member => ({ ...member, change: (updatedByIri.has(member.iri) ? "unchanged" : "removed") as MemberChange }))
    .sort(byName);
  const updated: ComparedMember[] = [...updatedByIri.values()]
    .map(member => ({ ...member, change: (currentByIri.has(member.iri) ? "unchanged" : "added") as MemberChange }))
    .sort(byName);

  const added = updated.filter(member => member.change === "added").length;
  const removed = current.filter(member => member.change === "removed").length;
  return { current, updated, added, removed, unchanged: updated.length - added };
}

/** True when the response holds fewer members than the total it reports, i.e. the comparison would be incomplete */
export function isTruncated(response?: SearchResponse): boolean {
  return !!response?.totalCount && response.totalCount > (response.entities?.length ?? 0);
}
